      "aggregations": [
        {
          "operation": "sum",
          "input_column": "current_value",
          "output_column": "total_current_value"
        },
        {
          "operation": "sum",
          "input_column": "cost",
          "output_column": "total_cost"
        }
      ]
    },
    {
      "id": "gain_component",
      "operator": "Math_Compute",
      "input": "gain_per_investor",
      "expression": "column('total_current_value') - column('total_cost')",
      "output_column": "gain_component"
