      "operator": "Integrate",
      "inputs": ["gain_component", "risk_component"],
      "left_on": ["investor_id"],
      "right_on": ["investor_id"],
      "join_type": "inner"
    },
    {
      "id": "gain_stats",
      "operator": "Filter_Aggregate",
      "input": "combined_metrics",
      "aggregations": [
        {
          "operation": "min",
          "input_column": "gain_component",
          "output_column": "min_gain"
        },
        {
          "operation": "max",
          "input_column": "gain_component",
          "output_column": "max_gain"
        }
      ]
    },
    {
      "id": "risk_stats",
      "operator": "Filter_Aggregate",
      "input": "combined_metrics",
      "aggregations": [
        {
          "operation": "min",
          "input_column": "risk_score",
          "output_column": "min_risk"
