      "id": "stats_broadcast",
      "operator": "Integrate",
      "inputs": ["gain_stats", "risk_stats"],
      "left_on": [],
      "right_on": [],
      "join_type": "inner"
    },
    {
      "id": "with_normalized_gain",
      "operator": "Math_Compute",
      "input": "combined_metrics",
      "expression": "(column('gain_component') - broadcast(column('min_gain', from='stats_broadcast'))) / nullif(broadcast(column('max_gain', from='stats_broadcast')) - broadcast(column('min_gain', from='stats_broadcast')), 0)",
      "output_column": "normalized_gain"
    },
    {
      "id": "with_normalized_risk",
      "operator": "Math_Compute",
      "input": "with_normalized_gain",
      "expression": "(column('risk_score') - broadcast(column('min_risk', from='stats_broadcast'))) / nullif(broadcast(column('max_risk', from='stats_broadcast')) - broadcast(column('min_risk', from='stats_broadcast')), 0)",
      "output_column": "normalized_risk"
    },
