      "id": "composite_scores",
      "operator": "Math_Compute",
      "input": "with_normalized_risk",
      "expression": "100 * ((column('normalized_gain') + column('normalized_risk')) / 2)",
      "output_column": "composite_score"
    },
    {
      "operator": "Order_By",
      "input": "composite_scores",
      "order_by": [
        {
          "column": "composite_score",
          "direction": "DESC"
        },
        {
          "column": "investor_id",
          "direction": "ASC"
        }
      ],
      "limit": 10
